package ro.leo.visual;
import android.content.*;import android.os.*;import android.widget.*;import java.io.*;import java.util.*;
public final class StorageSettingsActivity extends LeoActivity {
    protected void onResume(){super.onResume();show();}
    private void show(){final LinkedHashMap<String,File> roots=LeoFileProvider.roots(this);final ArrayList<File> folders=new ArrayList<File>();final ArrayList<String> labels=new ArrayList<String>();folders.add(Environment.getDataDirectory());labels.add("Date interne · "+capacity(Environment.getDataDirectory()));for(Map.Entry<String,File> root:roots.entrySet())if(!root.getKey().equals("leo")){folders.add(root.getValue());labels.add((root.getKey().equals("phone")?"Fișiere telefon":"Card SD")+" · "+capacity(root.getValue()));}final int locations=folders.size();labels.add("Salvare înregistrări · "+RecordingLocations.label(this));labels.add("Descărcări · "+(getSharedPreferences("downloads",0).getBoolean("wifi",true)?"Numai Wi-Fi":"Wi-Fi și mobil"));labels.add("Fișiere Leo");labels.add("Aplicații și spațiu APK");list("Stocare Leo",labels,0,new Choice(){public void pick(int at){if(at<locations)details(folders.get(at));else if(at==locations)recordings();else if(at==locations+1)options("Rețeaua descărcărilor noi",new String[]{"Numai Wi-Fi","Wi-Fi și date mobile"},new Choice(){public void pick(int n){getSharedPreferences("downloads",0).edit().putBoolean("wifi",n==0).apply();show();}});else startActivity(new Intent(StorageSettingsActivity.this,at==locations+2?FilesActivity.class:AppSettingsActivity.class));}},"Actualiz.",new Runnable(){public void run(){show();}});}
    static String capacity(File dir){try{StatFs stat=new StatFs(dir.getPath());return stat.getAvailableBytes()/1048576+" MiB liberi";}catch(RuntimeException e){return "indisponibil";}}
    private void details(File dir){String value;try{StatFs stat=new StatFs(dir.getPath());long total=stat.getTotalBytes(),available=stat.getAvailableBytes();value="Total · "+total/1048576+" MiB\nLiber · "+available/1048576+" MiB\nOcupat · "+(total-available)/1048576+" MiB\nUtilizare · "+(total>0?100-(int)(available*100/total):0)+"%\n\nAceastă pagină nu execută formatare sau ștergere.";}catch(RuntimeException e){value="Stocare indisponibilă";}begin("Spațiu disponibil");ScrollView scroll=new ScrollView(this);scroll.addView(text(value,18));root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));scroll.setFocusable(true);scroll.requestFocus();back=new Runnable(){public void run(){show();}};footer("","Derulează","Înapoi");}
    private void recordings(){final LinkedHashMap<String,File> places=RecordingLocations.folders(this);final ArrayList<String> keys=new ArrayList<String>(places.keySet()),labels=new ArrayList<String>();for(String key:keys)labels.add(key.equals("leo")?"Telefon · Documente Leo":"Card SD · dosar privat Leo");list("Salvare înregistrări",labels,Math.max(0,keys.indexOf(RecordingLocations.key(this))),new Choice(){public void pick(final int at){if(RecordingService.instance!=null){notice("Oprește înregistrarea înainte de schimbarea locației");return;}worker.execute(new Runnable(){public void run(){boolean writable=false;File probe=null;try{File dir=places.get(keys.get(at));if(!dir.isDirectory()&&!dir.mkdirs())throw new IOException();probe=File.createTempFile(".leo-storage-probe-",".tmp",dir);try(FileOutputStream out=new FileOutputStream(probe)){out.write(1);}writable=true;}catch(IOException e){}finally{if(probe!=null&&!probe.delete())writable=false;}final boolean ok=writable;ui(new Runnable(){public void run(){if(ok){getSharedPreferences("storage",0).edit().putString("recordings",keys.get(at)).apply();notice("Locație salvată; fișierele existente sunt păstrate");show();}else notice("Locația nu permite scrierea");}});}});}},"",null);back=new Runnable(){public void run(){show();}};}
}
